mapper.select:
SELECT

FROM xxl_job_operation_log AS t


        AND t.module = #{module}


        AND t.operation_type = #{operationType}


        AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


        AND t.operate_time >= #{operateTimeStart}


        AND t.operate_time <= #{operateTimeEnd}


        AND t.job_group_id = #{jobGroupId}


        AND t.target_name like CONCAT(CONCAT('%', #{targetName}), '%')


ORDER BY t.operate_time DESC
LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_job_operation_log AS t


        AND t.module = #{module}


        AND t.operation_type = #{operationType}


        AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


        AND t.operate_time >= #{operateTimeStart}


        AND t.operate_time <= #{operateTimeEnd}


        AND t.job_group_id = #{jobGroupId}


        AND t.target_name like CONCAT(CONCAT('%', #{targetName}), '%')
